//! Byte-for-byte parity with the verified TypeScript module.
//!
//! `tests/fixtures/hl_vectors.json` is generated by `scripts/hl-vectors.ts` from
//! `src/lib/hyperliquid/exchangeSigning.ts` (which matches the official SDK vectors).
//! `tests/hlParity.test.ts` regenerates it in CI and fails if it is stale.

use near_sdk::serde_json::{self, Value};
use zerodelta_risk_guard_v3::hl::{self, OrderWire, Tif};

const VECTORS: &str = include_str!("fixtures/hl_vectors.json");

fn v() -> Value {
    serde_json::from_str(VECTORS).unwrap()
}

fn u(x: &Value) -> u64 {
    match x {
        Value::String(s) => s.parse().unwrap(),
        other => other.as_u64().unwrap(),
    }
}

fn tif(s: &str) -> Tif {
    match s {
        "Alo" => Tif::Alo,
        "Ioc" => Tif::Ioc,
        "Gtc" => Tif::Gtc,
        _ => panic!("tif {}", s),
    }
}

#[test]
fn float_to_wire_matches_ts() {
    let v = v();
    let cases = v["wire"].as_array().unwrap();
    assert!(cases.len() >= 30);
    for c in cases {
        assert_eq!(hl::wire_e8(u(&c["e8"])), c["wire"].as_str().unwrap(), "x = {}", c["x"]);
    }
}

#[test]
fn every_order_action_matches_ts_byte_for_byte() {
    let v = v();
    let cases = v["orders"].as_array().unwrap();
    assert_eq!(cases.len(), 64);
    let mut checked_orders = 0;
    for c in cases {
        let id = &c["id"];
        let orders: Vec<OrderWire> = c["orders"]
            .as_array()
            .unwrap()
            .iter()
            .map(|o| OrderWire {
                asset: u(&o["asset"]) as u32,
                is_buy: o["isBuy"].as_bool().unwrap(),
                px_e8: u(&o["pxE8"]),
                sz_e8: u(&o["szE8"]),
                reduce_only: o["reduceOnly"].as_bool().unwrap(),
                tif: tif(o["tif"].as_str().unwrap()),
            })
            .collect();
        for (o, w) in orders.iter().zip(c["orders"].as_array().unwrap()) {
            assert_eq!(hl::wire_e8(o.px_e8), w["p"].as_str().unwrap(), "case {} p", id);
            assert_eq!(hl::wire_e8(o.sz_e8), w["s"].as_str().unwrap(), "case {} s", id);
            checked_orders += 1;
        }
        let nonce = u(&c["nonce"]);
        let packed = hl::to_msgpack(&hl::order_action(&orders));
        assert_eq!(hl::order_action_json(&orders), c["json"].as_str().unwrap(), "case {} json", id);
        assert_eq!(hl::hex(&packed), c["msgpackHex"].as_str().unwrap(), "case {} msgpack", id);
        let conn = hl::connection_id(&packed, nonce);
        assert_eq!(hl::hex(&conn), c["connectionIdHex"].as_str().unwrap(), "case {} connectionId", id);
        let digest = hl::l1_digest(&conn, c["isMainnet"].as_bool().unwrap());
        assert_eq!(hl::hex(&digest), c["digestHex"].as_str().unwrap(), "case {} digest", id);
        assert_eq!(digest, hl::order_digest(&orders, nonce, c["isMainnet"].as_bool().unwrap()));
    }
    assert!(checked_orders > 64, "multi-order actions are covered");
}

#[test]
fn sizing_is_exact_and_matches_ts_except_float_boundary_cases() {
    let v = v();
    let cases = v["sizing"].as_array().unwrap();
    let mut float_boundary = 0;
    for c in cases {
        let lots = hl::size_lots(u(&c["cents"]), u(&c["pxE8"]), u(&c["szDecimals"]) as u8).unwrap();
        // Rust is always the exact integer floor
        assert_eq!(lots, u(&c["exactLots"]), "{}", c);
        // The TS float version agrees except where float error lands just under a lot boundary
        let ts = u(&c["tsLots"]);
        if ts != lots {
            assert_eq!(lots, ts + 1, "float may only under-count by one lot: {}", c);
            float_boundary += 1;
        }
    }
    assert!(cases.len() >= 400);
    assert!(float_boundary * 50 < cases.len(), "float/exact disagreements are rare boundary cases ({})", float_boundary);
}
